mapper.select:
select laua.id, laua.activity_award_id, laua.name, laua.icon, laua.type, laua.num, laua.create_user_id, laua.update_user_id, laua.create_time, laua.update_time from la_activity_user_award laua
and laua.is_delete = 0
and laua.activity_award_id = #{param.activityAwardId}
and laua.name like concat('%',#{param.name},'%')
and laua.icon like concat('%',#{param.icon},'%')
and laua.type = #{param.type}
and laua.num = #{param.num}
and laua.create_user_id = #{param.createUserId}
and laua.update_user_id = #{param.updateUserId}
order by laua.id desc
